// Classe Abstrata (Compartilha Estado/Comportamento)
public abstract class NotaFiscal {
    private String descricao;
    public abstract double calcularImpostos();

    public void emitir() {
        System.out.println("Emitindo: " + descricao);
        System.out.println("Imposto: " + calcularImpostos());
    }
}

// Interface (Define Contrato)
public interface ClienteFinanciavel {
    double calcularLimiteAprovado();

    default double calcularJuros(double valor) {
        return valor * 0.1;
    }
}
